305	        return new ToStringCreator(this)
306	
307	            .append("id", this.getId())
308	            .append("new", this.isNew())
309	            .append("lastName", this.getLastName())
310	            .append("firstName", this.getFirstName())
311	            .append("address", this.address)
312	            .append("city", this.city)
313	            .append("telephone", this.telephone)
314	            .toString();
315	    }
316	}
