246	    /**
247	     * Maximum number of owners allowed in a single city. Creating an owner in a city that has
248	     * already reached this many owners is rejected as a conflict.
249	     */
250	    static final int MAX_OWNERS_PER_CITY = 50;
251	
252	    /**
253	     * Maximum number of owners allowed to register on a single day. Creating an owner once a day has
254	     * already reached this many registrations is rejected as a rate-limit violation.
255	     */
256	    static final int MAX_OWNERS_PER_DAY = 100;
257	
258	    /**
259	     * Number of owners that must already have registered on a day before a new registration is
260	     * flagged with a bulk-signup warning. Once the count already recorded for the day exceeds this
261	     * value, the new owner carries {@code bulkSignupWarning == true}.
262	     */
263	    static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
264	
265	    @Override
266	    @Transactional
267	    public String createOwner(Owner owner, boolean sharesHousehold) throws DataAccessException {
268	        if (DisposableEmailDomains.isDisposable(owner.getEmail())) {
269	            throw new DisposableEmailDomainException(owner.getEmail());
270	        }
271	        owner.setHouseholdId(HouseholdIdGenerator.generate(owner.getLastName(), owner.getPostcode()));
272	        rejectIdentityCollision(owner);
273	        List<Owner> householdMembers = findHouseholdMembers(owner);
274	        if (!householdMembers.isEmpty() && !sharesHousehold) {
275	            throw new HouseholdDuplicateException(owner.getHouseholdId());
276	        }
277	        long ownersInCity = ownerRepository.countByCity(owner.getCity());
278	        if (ownersInCity >= MAX_OWNERS_PER_CITY) {
279	            throw new CityCapacityExceededException(owner.getCity(), MAX_OWNERS_PER_CITY);
280	        }
281	        LocalDate effectiveDate = owner.getRegistrationDate() == null ? LocalDate.now() : owner.getRegistrationDate();
282	        owner.setRegistrationDate(BusinessDayAdjuster.toBusinessDay(effectiveDate));
283	        long ownersOnDate = ownerRepository.countByRegistrationDate(owner.getRegistrationDate());
284	        if (ownersOnDate >= MAX_OWNERS_PER_DAY) {
285	            throw new DailyOwnerLimitExceededException(owner.getRegistrationDate(), MAX_OWNERS_PER_DAY);
286	        }
287	        owner.setBulkSignupWarning(ownersOnDate > BULK_SIGNUP_WARNING_THRESHOLD);
288	        flagPossibleDuplicate(owner, householdMembers, sharesHousehold);
289	        owner.setNamesakeCount(countNamesakes(owner));
290	        owner.setHouseholdSize(householdMembers.size() + 1);
291	        owner.setCustomerCode(assignCustomerCode(owner));
292	        ownerRepository.save(owner);
293	        ownerAuditLogger.ownerCreated(owner);
294	        return owner.getHouseholdId();
295	    }
296	
297	    /**
298	     * Reject creating an owner whose whole {@link OwnerIdentityKey identity key} already belongs to
299	     * another owner. Because the telephone is part of the key, only an existing owner sharing every
300	     * key component (normalized telephone, email and household identifier) is a duplicate.
301	     */
302	    private void rejectIdentityCollision(Owner owner) {
303	        String identityKey = OwnerIdentityKey.of(owner);
304	        boolean collides = ownerRepository.findByTelephone(owner.getTelephone()).stream()
305	            .filter(ClinicServiceImpl::isActive)
306	            .anyMatch(existing -> identityKey.equals(OwnerIdentityKey.of(existing)));
307	        if (collides) {
308	            throw new DuplicateOwnerException(identityKey);
309	        }
310	    }
311	
312	    /**
313	     * Whether an existing owner is still active, i.e. has not been soft-deleted. Soft-deleted owners
314	     * are retained for history but ignored by the create-time duplicate and identity checks.
315	     */
316	    private static boolean isActive(Owner owner) {
317	        return !Boolean.TRUE.equals(owner.getDeleted());
318	    }
319	
320	    /**
321	     * Build the new owner's {@code customerCode} and de-duplicate it against existing owners. The
322	     * base code is derived from the owner's locality, telephone and last name; if it already belongs
323	     * to another owner it is suffixed with the smallest {@code "-<n>"} (n &gt;= 2) that is still free.
324	     */
325	    private String assignCustomerCode(Owner owner) {
326	        String baseCode = CustomerCodeGenerator.format(
327	            LocalityResolver.resolve(owner.getCity(), owner.getPostcode()),
328	            owner.getTelephone(), owner.getLastName());
329	        Set<String> takenCodes = ownerRepository.findByCustomerCodeStartingWith(baseCode).stream()
330	            .map(Owner::getCustomerCode)
331	            .collect(Collectors.toSet());
332	        return CustomerCodeGenerator.deduplicate(baseCode, takenCodes::contains);
333	    }
334	
335	    /**
336	     * Flag the new owner as a possible (soft) duplicate of an existing household member carrying a
337	     * different telephone. The new owner is still created; {@code possibleDuplicate} is set to
338	     * whether such a match exists and {@code possibleDuplicateOf} to the matching owner's id (the
339	     * lowest when several match), or {@code null} when there is no match.
340	     *
341	     * <p>An owner that explicitly declares {@code sharesHousehold} is a <em>declared</em> household
342	     * member rather than a suspected duplicate, so it is never flagged.
343	     */
344	    private void flagPossibleDuplicate(Owner owner, List<Owner> householdMembers, boolean sharesHousehold) {
345	        Owner match = sharesHousehold ? null : householdMembers.stream()
346	            .filter(existing -> !owner.getTelephone().equals(existing.getTelephone()))
347	            .min(Comparator.comparingInt(Owner::getId))
348	            .orElse(null);
349	        owner.setPossibleDuplicate(match != null);
350	        owner.setPossibleDuplicateOf(match == null ? null : match.getId());
351	    }
