359	    /**
360	     * Count the owners that already exist sharing this owner's first name and last name, compared
361	     * case-insensitively. Invoked before the new owner is persisted, so it never counts itself.
362	     */
363	    private int countNamesakes(Owner owner) {
364	        return (int) ownerRepository.findByLastNameIgnoreCase(owner.getLastName()).stream()
365	            .filter(existing -> owner.getFirstName().equalsIgnoreCase(existing.getFirstName()))
366	            .count();
367	    }
368	
369	    /**
370	     * Find the existing owners that already share this owner's household, i.e. that derive the same
371	     * computed {@code householdId} (the same last name and postcode). An owner without a postcode
372	     * has no household peers.
373	     */
374	    private List<Owner> findHouseholdMembers(Owner owner) {
375	        if (owner.getPostcode() == null) {
376	            return List.of();
377	        }
378	        String householdId = owner.getHouseholdId();
379	        return ownerRepository.findByLastNameIgnoreCase(owner.getLastName()).stream()
380	            .filter(ClinicServiceImpl::isActive)
381	            .filter(existing -> householdId.equals(
382	                HouseholdIdGenerator.generate(existing.getLastName(), existing.getPostcode())))
383	            .toList();
384	    }
