18	
19	import java.util.Optional;
20	import java.util.concurrent.ConcurrentHashMap;
21	import java.util.concurrent.ConcurrentMap;
22	
23	import org.springframework.stereotype.Component;
24	
25	/**
26	 * Remembers which owner a given {@code Idempotency-Key} first created, so a create that repeats
27	 * with an already-seen key can return the original owner instead of creating a duplicate.
28	 *
29	 * <p>Blank or absent keys are treated as "no key": they are never stored and never match, so
30	 * callers can pass the raw header value through without null-checking it first.
31	 */
32	@Component
33	public class IdempotencyKeyRegistry {
34	
35	    private final ConcurrentMap<String, Integer> ownerIdsByKey = new ConcurrentHashMap<>();
36	
37	    /** The id of the owner previously created under {@code key}, if any. */
38	    public Optional<Integer> ownerIdFor(String key) {
39	        if (key == null || key.isBlank()) {
40	            return Optional.empty();
41	        }
42	        return Optional.ofNullable(ownerIdsByKey.get(key));
43	    }
44	
45	    /** Associate {@code key} with the owner it created; a no-op for a blank or absent key. */
46	    public void remember(String key, Integer ownerId) {
47	        if (key != null && !key.isBlank()) {
48	            ownerIdsByKey.putIfAbsent(key, ownerId);
49	        }
50	    }
51	}
