17	    public boolean isValid(OwnerFieldsDto owner, ConstraintValidatorContext context) {
18	        if (owner == null) {
19	            return true;
20	        }
21	        String postcode = owner.getPostcode();
22	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
23	            return true;
24	        }
25	        if (PostcodePolicy.isValidForCity(owner.getCity(), postcode)) {
26	            return true;
27	        }
28	        context.disableDefaultConstraintViolation();
29	        context.buildConstraintViolationWithTemplate(context.getDefaultConstraintMessageTemplate())
30	            .addPropertyNode("postcode")
31	            .addConstraintViolation();
32	        return false;
33	    }
34	}
