83	    @Override
84	    public Owner findById(int id) {
85	        // using 'join fetch' because a single query should load both owners and pets
86	        // using 'left join fetch' because it might happen that an owner does not have pets yet
87	        Query query = this.em.createQuery("SELECT owner FROM Owner owner left join fetch owner.pets WHERE owner.id =:id");
88	        query.setParameter("id", id);
89	        return (Owner) query.getSingleResult();
90	    }
91	
92	
93	    @Override
94	    @SuppressWarnings("unchecked")
95	    public Collection<Owner> findByLastNameIgnoreCase(String lastName) throws DataAccessException {
96	        Query query = this.em.createQuery("SELECT owner FROM Owner owner WHERE LOWER(owner.lastName) = LOWER(:lastName)");
97	        query.setParameter("lastName", lastName);
