107	    }
108	
109	    @Override
110	    @SuppressWarnings("unchecked")
111	    public Collection<Owner> findByCustomerCodeStartingWith(String customerCode) throws DataAccessException {
112	        Query query = this.em.createQuery("SELECT owner FROM Owner owner WHERE owner.customerCode LIKE :customerCode");
113	        query.setParameter("customerCode", customerCode + "%");
114	        return query.getResultList();
115	    }
116	
117	    @Override
118	    public long count() throws DataAccessException {
119	        Query query = this.em.createQuery("SELECT COUNT(owner) FROM Owner owner");
120	        return (long) query.getSingleResult();
121	    }
122	
123	    @Override
124	    public long countByCity(String city) throws DataAccessException {
125	        Query query = this.em.createQuery(
126	            "SELECT COUNT(owner) FROM Owner owner WHERE UPPER(owner.city) = UPPER(:city)");
127	        query.setParameter("city", city);
128	        return (long) query.getSingleResult();
129	    }
130	
131	    @Override
132	    public long countByRegistrationDate(LocalDate registrationDate) throws DataAccessException {
133	        Query query = this.em.createQuery(
134	            "SELECT COUNT(owner) FROM Owner owner WHERE owner.registrationDate = :registrationDate");
135	        query.setParameter("registrationDate", registrationDate);
136	        return (long) query.getSingleResult();
137	    }
138	
139	    @Override
140	    public void save(Owner owner) {
141	        if (owner.getId() == null) {
142	            this.em.persist(owner);
143	        } else {
144	            this.em.merge(owner);
145	        }
146	
147	    }
148	
149		@SuppressWarnings("unchecked")
150		@Override
151		public Collection<Owner> findAll() throws DataAccessException {
152			Query query = this.em.createQuery("SELECT owner FROM Owner owner");
153	        return query.getResultList();
154		}
155	
156	    @SuppressWarnings("unchecked")
157	    @Override
158	    public Page<Owner> findAll(@NonNull Pageable pageable) throws DataAccessException {
159	        Query query = this.em.createQuery("SELECT owner FROM Owner owner ORDER BY owner.id");
160	        query.setFirstResult((int) pageable.getOffset());
161	        query.setMaxResults(pageable.getPageSize());
162	        List<Owner> owners = query.getResultList();
163	        Query countQuery = this.em.createQuery("SELECT COUNT(owner) FROM Owner owner");
164	        long total = (long) countQuery.getSingleResult();
165	        return new PageImpl<>(owners, pageable, total);
166	    }
167	
168		@Override
169		public void delete(Owner owner) throws DataAccessException {
170			this.em.remove(this.em.contains(owner) ? owner : this.em.merge(owner));
171		}
