46	/**
47	 * Global Exception handler for REST controllers.
48	 * <p>
49	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
50	 *
51	 * @author Vitaliy Fedoriv
52	 * @author Alexander Dudkin
53	 */
54	@ControllerAdvice
55	public class ExceptionControllerAdvice {
56	
57	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
58	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
59	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
60	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
61	    private static final String ERROR_DUPLICATE_OWNER = "An owner with the same identity (telephone, email and household) already exists";
62	    private static final String ERROR_HOUSEHOLD_DUPLICATE = "An owner already belongs to this household (same last name and postcode)";
63	    private static final String ERROR_CITY_CAPACITY = "The owner's city has already reached its maximum number of owners";
64	    private static final String ERROR_DAILY_OWNER_LIMIT = "The maximum number of owners for today has already been reached";
65	    private static final String ERROR_DISPOSABLE_EMAIL = "The owner's email uses a disposable domain that is not allowed";
66	
67	    /**
68	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
69	     * class.
70	     *
71	     * @param e     Object referring to the thrown exception.
72	     * @param status HTTP response status.
73	     * @param url URL request.
74	     */
75	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
76	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
77	        problemDetail.setType(URI.create(url.toString()));
78	        problemDetail.setTitle(e.getClass().getSimpleName());
79	        problemDetail.setDetail(detail);
80	        problemDetail.setProperty("timestamp", Instant.now());
81	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
82	        return problemDetail;
83	    }
84	
85	    /**
86	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
87	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
88	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
89	     * would catch it and report an authorization failure as a 500.
90	     *
91	     * @param e The {@link AccessDeniedException} to propagate
92	     * @throws AccessDeniedException always
93	     */
94	    @ExceptionHandler(AccessDeniedException.class)
95	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
96	        throw e;
97	    }
98	
99	    /**
100	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
101	     *
102	     * @param e The {@link Exception} to be handled
103	     * @param request {@link HttpServletRequest} object referring to the current request.
104	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
105	     */
106	    @ExceptionHandler(Exception.class)
107	    @ResponseBody
108	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
109	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
110	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
111	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
112	        return ResponseEntity.status(status).body(detail);
113	    }
114	
115	    /**
116	     * Handles {@link DuplicateOwnerException} raised when creating an owner whose whole identity key
117	     * (normalized telephone, email and household identifier) is already used by another owner,
118	     * returning a 409 Conflict status.
119	     *
120	     * @param e The {@link DuplicateOwnerException} to be handled
121	     * @param request {@link HttpServletRequest} object referring to the current request.
122	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status
123	     */
124	    @ExceptionHandler(DuplicateOwnerException.class)
125	    @ResponseBody
126	    public ResponseEntity<ProblemDetail> handleDuplicateOwnerException(DuplicateOwnerException e, HttpServletRequest request) {
127	        logger.warn("Duplicate owner identity at {} {}: {}",
128	            request.getMethod(),
129	            request.getRequestURI(),
130	            e.getMessage());
131	        HttpStatus status = HttpStatus.CONFLICT;
132	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DUPLICATE_OWNER);
133	        return ResponseEntity.status(status).body(detail);
134	    }
135	
136	    /**
137	     * Handles {@link HouseholdDuplicateException} raised when creating an owner into a household that
138	     * already has a member (another owner with the same last name and postcode) without declaring
139	     * {@code sharesHousehold}, returning a 409 Conflict status.
140	     *
141	     * @param e The {@link HouseholdDuplicateException} to be handled
142	     * @param request {@link HttpServletRequest} object referring to the current request.
143	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status
144	     */
145	    @ExceptionHandler(HouseholdDuplicateException.class)
146	    @ResponseBody
147	    public ResponseEntity<ProblemDetail> handleHouseholdDuplicateException(HouseholdDuplicateException e, HttpServletRequest request) {
148	        logger.warn("Household duplicate at {} {}: {}",
149	            request.getMethod(),
150	            request.getRequestURI(),
151	            e.getMessage());
152	        HttpStatus status = HttpStatus.CONFLICT;
153	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_HOUSEHOLD_DUPLICATE);
154	        return ResponseEntity.status(status).body(detail);
155	    }
156	
157	    /**
158	     * Handles {@link CityCapacityExceededException} raised when creating an owner in a city that has already
159	     * reached its maximum number of owners, returning a 409 Conflict status.
160	     *
161	     * @param e The {@link CityCapacityExceededException} to be handled
162	     * @param request {@link HttpServletRequest} object referring to the current request.
163	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status
164	     */
165	    @ExceptionHandler(CityCapacityExceededException.class)
166	    @ResponseBody
167	    public ResponseEntity<ProblemDetail> handleCityCapacityExceededException(CityCapacityExceededException e, HttpServletRequest request) {
168	        logger.warn("City capacity exceeded at {} {}: {}",
169	            request.getMethod(),
170	            request.getRequestURI(),
171	            e.getMessage());
172	        HttpStatus status = HttpStatus.CONFLICT;
173	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_CITY_CAPACITY);
174	        return ResponseEntity.status(status).body(detail);
175	    }
176	
177	    /**
178	     * Handles {@link DailyOwnerLimitExceededException} raised when creating an owner on a day that has already
179	     * reached its maximum number of registrations, returning a 429 Too Many Requests status.
180	     *
181	     * @param e The {@link DailyOwnerLimitExceededException} to be handled
182	     * @param request {@link HttpServletRequest} object referring to the current request.
183	     * @return A {@link ResponseEntity} containing the error information and a 429 Too Many Requests status
184	     */
185	    @ExceptionHandler(DailyOwnerLimitExceededException.class)
186	    @ResponseBody
187	    public ResponseEntity<ProblemDetail> handleDailyOwnerLimitExceededException(DailyOwnerLimitExceededException e, HttpServletRequest request) {
188	        logger.warn("Daily owner limit exceeded at {} {}: {}",
189	            request.getMethod(),
190	            request.getRequestURI(),
191	            e.getMessage());
192	        HttpStatus status = HttpStatus.TOO_MANY_REQUESTS;
193	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DAILY_OWNER_LIMIT);
194	        return ResponseEntity.status(status).body(detail);
195	    }
196	
197	    /**
198	     * Handles {@link DisposableEmailDomainException} raised when creating an owner whose email domain is on the
199	     * disposable-domain blocklist, returning a 400 Bad Request status.
200	     *
201	     * @param e The {@link DisposableEmailDomainException} to be handled
202	     * @param request {@link HttpServletRequest} object referring to the current request.
203	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status
204	     */
205	    @ExceptionHandler(DisposableEmailDomainException.class)
206	    @ResponseBody
207	    public ResponseEntity<ProblemDetail> handleDisposableEmailDomainException(DisposableEmailDomainException e, HttpServletRequest request) {
208	        logger.warn("Disposable email domain at {} {}: {}",
209	            request.getMethod(),
210	            request.getRequestURI(),
211	            e.getMessage());
212	        HttpStatus status = HttpStatus.BAD_REQUEST;
213	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DISPOSABLE_EMAIL);
214	        return ResponseEntity.status(status).body(detail);
215	    }
216	
217	    /**
218	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
219	     * method returns a 404 Not Found status if an entity does not exist.
220	     *
221	     * @param e The {@link DataIntegrityViolationException} to be handled
222	     * @param request {@link HttpServletRequest} object referring to the current request.
223	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
224	     */
225	    @ExceptionHandler(DataIntegrityViolationException.class)
226	    @ResponseBody
227	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
228	        logger.warn("Data integrity violation at {} {}: {}",
229	            request.getMethod(),
230	            request.getRequestURI(),
231	            e.getMessage());
232	        logger.debug("Data integrity violation stacktrace", e);
233	        HttpStatus status = HttpStatus.NOT_FOUND;
234	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
235	        return ResponseEntity.status(status).body(detail);
236	    }
237	
238	    /**
239	     * Handles exception thrown by Bean Validation on controller methods parameters
240	     *
241	     * @param e The {@link MethodArgumentNotValidException} to be handled
242	     * @param request {@link HttpServletRequest} object referring to the current request.
243	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
244	     */
245	    @ExceptionHandler(MethodArgumentNotValidException.class)
246	    @ResponseBody
247	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
248	        HttpStatus status = HttpStatus.BAD_REQUEST;
249	        BindingErrorsResponse errors = new BindingErrorsResponse();
250	        BindingResult bindingResult = e.getBindingResult();
251	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
252	        detail.setProperty("errors", bindingResult.getFieldErrors().stream()
253	            .map(FieldError::getField)
254	            .distinct()
255	            .toList());
256	        if (bindingResult.hasErrors()) {
257	            errors.addAllErrors(bindingResult);
258	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
259	                .map(fieldError -> {
260	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
261	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
262	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
263	                        fieldError.getField(),
264	                        defaultMessage,
265	                        rejectedValue);
266	                    return new ValidationMessageDto(message)
267	                        .putAdditionalProperty("field", fieldError.getField())
268	                        .putAdditionalProperty("rejectedValue", rejectedValue)
269	                        .putAdditionalProperty("defaultMessage", defaultMessage);
270	                })
271	                .toList();
272	            logger.debug("Validation error at {} {}: {}",
273	                request.getMethod(),
274	                request.getRequestURI(),
275	                bindingResult.getFieldErrors());
276	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
277	            return ResponseEntity.status(status).body(detail);
278	        }
279	        return ResponseEntity.status(status).body(detail);
280	    }
281	
282	}
