17	package org.springframework.samples.petclinic.util;
18	
19	import java.util.Optional;
20	import java.util.regex.Pattern;
21	
22	/**
23	 * Converts telephone numbers to canonical E.164 form. Shared by the create-time validation
24	 * constraint and the mapping that stores the value, so both agree on what a valid, stored
25	 * telephone looks like.
26	 *
27	 * <p>A leading {@code '+'} with its country code is kept as given; otherwise the Australian
28	 * country code {@code '+61'} is assumed and a single leading {@code '0'} is dropped from the
29	 * national digits. Spaces, dashes and brackets are ignored. The digits following the
30	 * {@code '+'} must number between 8 and 15 inclusive, and for a recognised country calling
31	 * code the national-number length must match what that country requires (see
32	 * {@link CountryCallingCode}).
33	 */
34	public final class TelephoneNormalizer {
35	
36	    /** Country code assumed when the number carries no explicit {@code '+'} prefix. */
37	    private static final String DEFAULT_COUNTRY_CODE = "61";
38	
39	    /** Separators that carry no meaning and are stripped before parsing. */
40	    private static final Pattern SEPARATORS = Pattern.compile("[\\s()\\-]");
41	
42	    private static final int MIN_DIGITS = 8;
43	    private static final int MAX_DIGITS = 15;
44	
45	    private TelephoneNormalizer() {
46	    }
47	
48	    /**
49	     * Convert the given telephone value to E.164 form.
50	     *
51	     * @param telephone the raw telephone value (may be {@code null})
52	     * @return the E.164 string (a {@code '+'} followed by 8 to 15 digits), or
53	     * {@link Optional#empty()} when {@code telephone} is {@code null} or cannot form valid E.164
54	     */
55	    public static Optional<String> toE164(String telephone) {
56	        if (telephone == null) {
57	            return Optional.empty();
58	        }
59	        String cleaned = SEPARATORS.matcher(telephone).replaceAll("");
60	        String digits;
61	        if (cleaned.startsWith("+")) {
62	            digits = cleaned.substring(1);
63	        } else {
64	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
65	            digits = DEFAULT_COUNTRY_CODE + national;
66	        }
67	        if (digits.length() < MIN_DIGITS || digits.length() > MAX_DIGITS || !isAllDigits(digits)) {
68	            return Optional.empty();
69	        }
70	        Optional<CountryCallingCode> country = CountryCallingCode.forDigits(digits);
71	        if (country.isPresent() && !country.get().hasValidNationalLength(digits)) {
72	            return Optional.empty();
73	        }
74	        return Optional.of("+" + digits);
75	    }
76	
77	    private static boolean isAllDigits(String value) {
78	        for (int i = 0; i < value.length(); i++) {
79	            char c = value.charAt(i);
80	            if (c < '0' || c > '9') {
81	                return false;
82	            }
83	        }
84	        return true;
85	    }
86	}
