17	package org.springframework.samples.petclinic.util;
18	
19	import java.util.Locale;
20	
21	/**
22	 * Normalizes email addresses to their canonical lower-cased form, so an owner's email is
23	 * always stored and returned the same way regardless of the casing the client supplied.
24	 */
25	public final class EmailNormalizer {
26	
27	    private EmailNormalizer() {
28	    }
29	
30	    /**
31	     * Lower-case the given email value.
32	     *
33	     * @param email the raw email value (may be {@code null})
34	     * @return the lower-cased email, or {@code null} when {@code email} is {@code null}
35	     */
36	    public static String normalize(String email) {
37	        if (email == null) {
38	            return null;
39	        }
40	        return email.toLowerCase(Locale.ROOT);
41	    }
42	}
